/** Whether `action` may happen to `target` at `at`, and every restriction in the way. */
export function check({ action, target, restrictions, at }: {
  action: "send" | "publish";
  target: { teamId: string; sendingDomainId?: string; emailMessageId?: string };
  restrictions: Restriction[];
  at: Date;
}) {
  const blocking = restrictions.filter(
    (r) => inEffect(r, at) && r.effect === action && covers(r, target)
  );
  return { allowed: blocking.length === 0, blocking };
}

const inEffect = (r, at) =>
  r.createdAt <= at && (r.liftedAt === null || r.liftedAt > at);
```

- **Pure.** No DB, no clock — the model wrapper loads rows and passes `now`.
- **Time is a parameter.** The timeline is `check` at each row's start and end; tests are a table of rows and a moment.
- **Status per target:** none blocking → *sending*; any not upheld → *waiting for review*; all upheld → *confirmed*.
- **Allowances don't appear.** They never unblock anything; they stop detectors writing a new restriction.
